    async function renderTimeline(jobId){try{const r=await fetch(`/api/jobs/${encodeURIComponent(jobId)}/timeline`);const data=await r.json();if(!r.ok)throw Error(data.error||data.detail||'Timeline unavailable');const duration=Math.max(0,finiteNumber(data.duration));const segments=Array.isArray(data.segments)?data.segments.filter(s=>s&&typeof s==='object'):[];$('timelineBadge').textContent=`${segments.length} transcript segments`;$('timelineEnd').textContent=fmtTime(duration);$('timelineTrack').innerHTML=segments.length?segments.map((s,i)=>{const start=Math.max(0,finiteNumber(s.start));const end=Math.max(start,finiteNumber(s.end,start));const left=duration?Math.min(100,Math.max(0,start/duration*100)):0;const width=duration?Math.max(1,(end-start)/duration*100):4;return `<button class="timeline-segment" data-segment="${i}" style="left:${left}%;width:${Math.min(100-left,width)}%" title="${esc(s.text||'')}">${esc(s.text||'')}</button>`;}).join(''):'<div class="empty" style="border:0;padding:18px">No transcript segments.</div>';$('transcriptList').innerHTML=segments.length?segments.map((s,i)=>`<button class="transcript-row" data-segment="${i}"><time>${fmtTime(s.start)}</time><span>${esc(s.text||'')}</span></button>`).join(''):'<div class="empty" style="padding:15px">No transcript segments.</div>';document.querySelectorAll('[data-segment]').forEach(b=>b.addEventListener('click',()=>{const s=segments[Number(b.dataset.segment)];if(!s)return;$('startTime').value=Math.max(0,finiteNumber(s.start)).toFixed(1);$('endTime').value=Math.max(.1,finiteNumber(s.end,.1)).toFixed(1);updateCaptionOverlay();toast(`Selected transcript segment at ${fmtTime(s.start)}.`);}));renderWaveform(jobId);}catch(e){toast(e.message,true);}}
    async function renderWaveform(jobId){try{const r=await fetch(`/api/jobs/${encodeURIComponent(jobId)}/waveform`);const data=await r.json();if(!r.ok||!Array.isArray(data.peaks)||!data.peaks.length){$('waveformTrack').innerHTML='<span class="dropzone-sub">No audio waveform available.</span>';return;}$('waveformTrack').innerHTML=data.peaks.map(p=>`<i class="waveform-bar" style="height:${Math.max(4,Math.round(Math.min(1,Math.max(0,finiteNumber(p)))*100))}%"></i>`).join('');}catch(e){$('waveformTrack').innerHTML='';}}
    function updateCaptionOverlay(){const clip=selectedClip();const text=clip?.hook_sentence||clip?.title||'';$('captionOverlay').textContent=text;$('captionOverlay').hidden=!text||!state.result;$('captionOverlay').className=`caption-overlay ${$('captionPosition').value} ${$('captionStyle').value==='boxed'?'boxed':''}`;$('captionOverlay').style.fontFamily=$('captionFont').value||'Arial';$('captionOverlay').style.fontSize=`${Math.max(12,Number($('captionSize').value)||17)}px`;$('captionOverlay').style.color=$('captionColor').value||'#fff';}
