    async function uploadFile(file){if(!file)return;state.uploading=true;$('chooseFile').disabled=true;$('uploadStatus').textContent=`Uploading ${file.name}...`;const body=new FormData();body.append('file',file,file.name);try{const r=await fetch('/api/uploads',{method:'POST',body});const data=await r.json();if(!r.ok)throw Error(data.error||data.detail||'Upload failed');$('sourceInput').value=data.path;$('mode').value='local';$('uploadStatus').textContent=`Ready: ${data.name} (${Math.round(data.size/1024/1024)} MB)`;toast('Video uploaded and ready.');}catch(e){$('uploadStatus').textContent=`Upload failed: ${e.message}`;toast(e.message,true);}finally{state.uploading=false;$('chooseFile').disabled=false;}}
    function setUpdateStatus(message, busy=false) { const status=$('updateStatus'); if(status) status.textContent=String(message||''); const button=$('updateButton'); if(button) button.setAttribute('aria-busy',String(Boolean(busy))); }
    function releaseUrl(info) { return String(info?.url||'https://github.com/wiifhub/AI-Youtube-Shorts-Generator/releases'); }
    function renderUpdate(info) {
      state.update = info && typeof info === 'object' ? info : null;
      const button=$('updateButton'); if(!button) return;
      button.disabled=false; button.removeAttribute('aria-busy');
      const version=$('settingsVersion'); if(version && info?.current_version) version.textContent=`v${info.current_version}`;
      if(!info || !info.available) { button.textContent='Check for updates'; setUpdateStatus(`Could not reach GitHub${info?.error?`: ${info.error}`:'. Try again later.'}`); return; }
      if(info.update_available) {
        if(info.can_install) { button.textContent=`Install v${info.latest_version}`; setUpdateStatus(`Shorts Studio v${info.latest_version} is ready. Click Install to download and restart automatically.`); }
        else { button.textContent=`Open v${info.latest_version}`; setUpdateStatus(`v${info.latest_version} is available. This source install needs the release page to update manually.`); }
      } else { button.textContent='Check for updates'; setUpdateStatus(`You're up to date - Shorts Studio v${info.current_version}.`); }
    }
    async function checkForUpdates(showToast=true) {
      if(state.updateBusy) return;
      state.updateBusy=true; const button=$('updateButton'); if(button){button.disabled=true;button.textContent='Checking...';} setUpdateStatus('Checking wiifhub/AI-Youtube-Shorts-Generator...',true);
      try { const r=await fetch('/api/update',{cache:'no-store'}); const data=await r.json(); if(!r.ok) throw Error(data.error||data.detail||'Update check failed'); renderUpdate(data); if(showToast) toast(data.available?(data.update_available?`Update v${data.latest_version} found.`:`You're up to date on v${data.current_version}.`):'Update check unavailable',!data.available); }
      catch(e) { state.update=null; renderUpdate({available:false,error:e.message}); if(showToast) toast(`Update check failed: ${e.message}`,true); }
      finally { state.updateBusy=false; }
    }
    function updateProgressText(data) { const total=finiteNumber(data?.total); const progress=finiteNumber(data?.progress); const pct=total>0?` ${Math.min(100,Math.round(progress/total*100))}%`:''; return data?.status==='starting'?'Preparing update...':data?.status==='downloading'?`Downloading update...${pct}`:data?.status==='restarting'?'Update downloaded. Restarting Shorts Studio...':data?.message||'Updating...'; }
    async function pollUpdate() {
      if(state.updatePoll) clearTimeout(state.updatePoll); state.updatePoll=null;
      try { const r=await fetch('/api/update/status',{cache:'no-store'}); const data=await r.json(); setUpdateStatus(updateProgressText(data),['starting','downloading','restarting'].includes(data.status)); if(data.status==='restarting'){toast('Update downloaded. Shorts Studio is restarting...');return;} if(data.status==='error'){state.updateBusy=false;const button=$('updateButton');if(button){button.disabled=false;button.textContent='Check for updates';}toast(data.error||'Update failed',true);return;} if(['starting','downloading'].includes(data.status)){state.updatePoll=setTimeout(pollUpdate,800);} else {state.updateBusy=false;const button=$('updateButton');if(button)button.disabled=false;} }
      catch(e) { state.updateBusy=false; const button=$('updateButton');if(button){button.disabled=false;button.textContent='Check for updates';} setUpdateStatus(`Update status unavailable: ${e.message}`); }
    }
    function openRelease(info) { const url=releaseUrl(info); const popup=window.open(url,'_blank','noopener,noreferrer'); if(!popup) window.location.href=url; }
    async function applyUpdate() {
      if(state.updateBusy) return;
      const info=state.update; if(!info?.update_available) { await checkForUpdates(); return; }
      if(!info.can_install) { openRelease(info); return; }
      if(!confirm(`Download Shorts Studio v${info.latest_version} and restart? Your projects and settings will be preserved.`)) return;
      state.updateBusy=true; const button=$('updateButton'); if(button){button.disabled=true;button.textContent='Updating...';} setUpdateStatus('Starting update...',true);
      try { const r=await fetch('/api/update/apply',{method:'POST'}); const data=await r.json(); if(!r.ok) throw Error(data.error||data.detail||'Update failed'); if(data.status==='manual'){openRelease(data);state.updateBusy=false;renderUpdate(data);return;} if(data.status==='current'){state.updateBusy=false;renderUpdate(data);toast('Already up to date.');return;} if(data.status==='error') throw Error(data.error||data.message||'Update failed'); pollUpdate(); }
      catch(e) { state.updateBusy=false; renderUpdate({available:true,update_available:true,can_install:Boolean(info.can_install),latest_version:info.latest_version,current_version:info.current_version,url:info.url,error:e.message}); setUpdateStatus(`Update failed: ${e.message}`); toast(`Update failed: ${e.message}`,true); }
    }
