    $('preset').addEventListener('change',()=>{const p={podcast:{captionStyle:'bold',focus:'balanced',fitMode:'fit_blur',zoom:.92,normalizeAudio:true},educational:{captionStyle:'clean',focus:'educational',fitMode:'crop',zoom:1,normalizeAudio:true},reaction:{captionStyle:'karaoke',focus:'funny',fitMode:'crop',zoom:1.08,normalizeAudio:true},story:{captionStyle:'boxed',focus:'story',fitMode:'fit_blur',zoom:.9,normalizeAudio:true},kids:{captionStyle:'bold',captionPosition:'bottom',captionFont:'Arial',captionColor:'#ffe066',focus:'visual',fitMode:'fit_blur',zoom:.98,normalizeAudio:true,denoiseAudio:true}}[$('preset').value];if(!p)return;Object.entries(p).forEach(([id,value])=>{const el=$(id);if(!el)return;if(el.type==='checkbox')el.checked=Boolean(value);else el.value=value;});syncFrameClass();updateLabels();});
    async function loadSettingsDetails(){try{const r=await fetch('/api/system',{cache:'no-store'});const info=await r.json();if(!r.ok)throw Error(info.detail||'Diagnostics unavailable');const storage=info.setup?.storage||{};const root=storage.output_root||info.output_root||'Configured output folder';const free=storage.free_disk_gb??info.free_disk_gb;const min=storage.minimum_free_gb;const suffix=free===undefined?'':` - ${free} GB free${min===undefined?'':` (minimum ${min} GB)`}`;$('settingsStorageDetails').textContent=`${root}${suffix}`;}catch(e){$('settingsStorageDetails').textContent='Storage details unavailable';}}
